.ah-vp,.ah-ctl,.ah-volume,.ah-bundle-legacy{display:none!important}
#ahBundle{--ink:#111;--muted:#7b7b7b;--line:#e5e5e3;--soft:#f2f1ef;--dark:#1e2a3a;--red:#d63a2e;font-family:'Poppins',-apple-system,"Segoe UI",Roboto,Arial,sans-serif;color:var(--ink);max-width:560px;margin:26px 0}
#ahBundle *{box-sizing:border-box}
#ahBundle .ah-div{display:flex;align-items:center;gap:14px;margin:6px 0 16px}
#ahBundle .ah-div:before,#ahBundle .ah-div:after{content:"";flex:1;height:1px;background:var(--line)}
#ahBundle .ah-div span{font-size:13.5px;font-weight:700;white-space:nowrap}
#ahBundle .ah-t{position:relative;display:flex;align-items:flex-start;gap:14px;background:var(--soft);border:2px solid transparent;border-radius:10px;padding:17px 18px;margin:11px 0;cursor:pointer}
#ahBundle .ah-t.sel{background:#fff;border-color:var(--ink)}
#ahBundle .ah-r{width:22px;height:22px;border-radius:50%;border:2px solid #bdbdbd;flex:0 0 auto;margin-top:1px;position:relative;background:#fff}
#ahBundle .ah-t.sel .ah-r{border-color:var(--ink)}
#ahBundle .ah-t.sel .ah-r:after{content:"";position:absolute;inset:3px;border-radius:50%;background:var(--ink)}
#ahBundle .ah-m{flex:1;min-width:0}
#ahBundle .ah-each{font-size:18px;font-weight:700;line-height:1.15;display:flex;align-items:center;gap:8px;flex-wrap:wrap}
#ahBundle .ah-desc{font-size:12.5px;color:var(--muted);margin-top:4px;line-height:1.45;font-weight:400}
#ahBundle .ah-p{text-align:right;flex:0 0 auto;padding-left:8px}
#ahBundle .ah-tot{font-size:18px;font-weight:700}
#ahBundle .ah-was{font-size:13px;color:var(--muted);text-decoration:line-through;font-weight:400;margin-top:1px}
#ahBundle .ah-rib{position:absolute;top:-11px;right:16px;font-size:10px;font-weight:700;letter-spacing:.11em;text-transform:uppercase;padding:4px 10px;border-radius:5px;background:var(--ink);color:#fff}
#ahBundle .ah-low{font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#fff;background:var(--red);padding:3px 8px;border-radius:5px}
#ahBundle .ah-mix{margin-top:14px;display:none}
#ahBundle .ah-t.sel .ah-mix{display:block}
#ahBundle .ah-mixhd{font-size:12px;color:var(--muted);font-weight:500;margin-bottom:8px}
#ahBundle .ah-row{display:flex;align-items:center;gap:8px;margin:7px 0}
#ahBundle .ah-no{font-size:12px;color:var(--muted);width:22px;font-weight:500}
#ahBundle .ah-cbox{flex:1;display:flex;align-items:center;gap:8px;border:1px solid #dcdcda;border-radius:8px;padding:5px 8px;background:#fff}
#ahBundle .ah-th{width:26px;height:26px;border-radius:5px;background-size:cover;background-position:center;flex:0 0 auto;border:1px solid #eee}
#ahBundle .ah-cs{flex:1;border:none;background:transparent;font-size:13px;font-weight:500;font-family:inherit;color:#111;outline:none;-webkit-appearance:none;appearance:none;padding:4px 2px}
#ahBundle .ah-ss{width:78px;flex:0 0 auto;border:1px solid #dcdcda;border-radius:8px;padding:8px 8px;background:#fff;font-size:13px;font-weight:500;font-family:inherit;color:#111}
#ahBundle .ah-cta{display:flex;align-items:center;justify-content:center;gap:9px;width:100%;margin-top:16px;padding:17px;background:var(--dark);color:#fff;border:none;border-radius:9px;font-size:15.5px;font-weight:700;letter-spacing:.02em;cursor:pointer}
#ahBundle .ah-cta[disabled]{opacity:.6;cursor:default}
#ahBundle .ah-cta .sv{font-weight:600;opacity:.9}
#ahBundle .ah-tr{display:flex;justify-content:center;gap:20px;margin-top:13px;flex-wrap:wrap}
#ahBundle .ah-tr span{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:5px;font-weight:500}
#ahBundle .ah-tr b{color:#2f8a4e}



